mapper.select:
select id, type, title, leader, start_time, create_at,leader_name
from teamup



        type=#{type}



    order by ${sortRules}

SELECT id, type,CONTENT,create_time FROM circle

where category = 'Dynamics'

    order by ${sortRules}

SELECT id, type, bounty, request_content, note, user_id, create_time FROM circle
WHERE category = 'Task'
order by ${sortRules}

SELECT id,user_id,title,picture,start_time,end_time FROM circle


    category = 'Event'


    order by ${sortRules}

SELECT ct.id as id, ct.teamup_id as teamup_id, ct.parent_id as parent_id, ct.text as text, ct.picture as picture, ct.son as son, ct.create_time as create_time,
ct.user_id as user_id, U1.avatar as user_avatar, U1.user_name as user_name,
ct.reply_user_id as reply_user_id, U2.avatar as reply_user_avatar, U2.user_name as reply_user_name FROM comment_teamup AS ct LEFT JOIN user U1 ON U1.user_id = ct.user_id LEFT JOIN user U2 ON U2.user_id = ct.reply_user_id WHERE ct.teamup_id=#{teamUpId}

SELECT ct.id as id, ct.teamup_id as teamup_id, ct.parent_id as parent_id, ct.text as text, ct.picture as picture, ct.son as son, ct.create_time as create_time,
ct.user_id as user_id, U1.avatar as user_avatar, U1.user_name as user_name,
ct.reply_user_id as reply_user_id, U2.avatar as reply_user_avatar, U2.user_name as reply_user_name FROM comment_teamup AS ct LEFT JOIN user U1 ON U1.user_id = ct.user_id LEFT JOIN user U2 ON U2.user_id = ct.reply_user_id WHERE ct.id=#{id}

WITH RECURSIVE CommentPath AS ( SELECT id, teamup_id, parent_id, text, picture, son, user_id, reply_user_id, create_time, 0 AS level FROM comment_teamup WHERE id = #{commentId}
UNION ALL
SELECT c.id, c.teamup_id, c.parent_id, c.text, c.picture, c.son, c.user_id, c.reply_user_id, c.create_time, cp.level + 1 AS level FROM comment_teamup c INNER JOIN CommentPath cp ON c.id = cp.parent_id) SELECT cp.id AS id, cp.teamup_id AS teamup_id, cp.parent_id AS parent_id, cp.text AS text, cp.picture AS picture, cp.son AS son, cp.create_time AS create_time, cp.level AS level, cp.user_id AS user_id, U1.avatar AS user_avatar, U1.user_name AS user_name, cp.reply_user_id AS reply_user_id, U2.avatar AS reply_user_avatar, U2.user_name AS reply_user_name FROM CommentPath cp LEFT JOIN user U1 ON U1.user_id = cp.user_id LEFT JOIN user U2 ON U2.user_id = cp.reply_user_id ORDER BY cp.level DESC

SELECT ct.id as id, ct.circle_id as circle_id, ct.parent_id as parent_id, ct.text as text, ct.picture as picture, ct.son as son, ct.create_time as create_time,
ct.user_id as user_id, U1.avatar as user_avatar, U1.user_name as user_name,
ct.reply_user_id as reply_user_id, U2.avatar as reply_user_avatar, U2.user_name as reply_user_name FROM comment_circle AS ct LEFT JOIN user U1 ON U1.user_id = ct.user_id LEFT JOIN user U2 ON U2.user_id = ct.reply_user_id WHERE ct.circle_id=#{circleId}

WITH RECURSIVE CommentPath AS ( SELECT id, circle_id, parent_id, text, picture, son, user_id, reply_user_id, create_time, 0 AS level FROM comment_circle WHERE id = #{commentId}
UNION ALL
SELECT c.id, c.circle_id, c.parent_id, c.text, c.picture, c.son, c.user_id, c.reply_user_id, c.create_time, cp.level + 1 AS level FROM comment_circle c INNER JOIN CommentPath cp ON c.id = cp.parent_id) SELECT cp.id AS id, cp.circle_id AS circle_id, cp.parent_id AS parent_id, cp.text AS text, cp.picture AS picture, cp.son AS son, cp.create_time AS create_time, cp.level AS level, cp.user_id AS user_id, U1.avatar AS user_avatar, U1.user_name AS user_name, cp.reply_user_id AS reply_user_id, U2.avatar AS reply_user_avatar, U2.user_name AS reply_user_name FROM CommentPath cp LEFT JOIN user U1 ON U1.user_id = cp.user_id LEFT JOIN user U2 ON U2.user_id = cp.reply_user_id ORDER BY cp.level DESC
